from app.models import Product, StockRow


def low_stock_products(
    products: list[Product], rows: list[StockRow], threshold: int
) -> list[Product]:
    """Products whose total stock across all warehouses is below `threshold`."""
    result = []
    for product in products:
        total = 0
        for row in rows:
            if row.product_id == product.id:
                total += row.quantity
        if 0 < total < threshold:
            result.append(product)
    return result
